import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M10 4a2 2 0 1 1 2 2H4a1 1 0 0 0 0 2h8a4 4 0 1 0-4-4 1 1 0 0 0 2 0M1 9a1 1 0 1 0 0 2h7.5a1.5 1.5 0 0 1 0 3c-.749 0-1.386-.538-1.52-1.199a1 1 0 1 0-1.96.398C5.35 14.82 6.83 16 8.5 16a3.5 3.5 0 1 0 0-7z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M12 6a3 3 0 1 1 3 3H4a1 1 0 0 0 0 2h11a5 5 0 1 0-5-5 1 1 0 1 0 2 0M1 12a1 1 0 1 0 0 2h10a2 2 0 1 1 0 4c-.934 0-1.803-.614-2.057-1.333a1 1 0 1 0-1.886.666C7.627 18.944 9.321 20 11 20a4 4 0 0 0 0-8z"] as readonly string[];

export const WindIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="wind" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
WindIcon.displayName = `Blueprint6.Icon.WindIcon`;

/**
 * @deprecated Use {@link WindIcon} instead.
 */
export const Wind: typeof WindIcon = WindIcon;

export default WindIcon;
